const fs=require('fs'),p=require('path'),c=require('crypto');
const need=(v,m)=>{if(!v)throw Error(m)},fields=['dev','ino','mode','size','mtimeNs','ctimeNs','nlink'];
function readExact(i){const x=i.path;need(p.isAbsolute(x)&&p.normalize(x)===x,'absolute normalized');let a='/';for(const k of x.split('/').filter(Boolean)){a=p.join(a,k);need(!fs.lstatSync(a).isSymbolicLink(),'symlink');}const s=fs.lstatSync(x,{bigint:true});need(s.isFile()&&s.size<=67108864n,'regular cap');if(i.bytes!==undefined)need(s.size===BigInt(i.bytes),'initial size');const same=t=>fields.every(k=>t[k]===s[k]);const fd=fs.openSync(x,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let b;try{need(same(fs.fstatSync(fd,{bigint:true})),'fd-before');const chunks=[];let n=0,cap=Number(s.size)+1;while(n<cap){const z=Buffer.alloc(Math.min(65536,cap-n)),g=fs.readSync(fd,z,0,z.length,null);if(!g)break;chunks.push(z.subarray(0,g));n+=g;}b=Buffer.concat(chunks);need(b.length===Number(s.size)&&same(fs.fstatSync(fd,{bigint:true})),'fd-after/length');}finally{fs.closeSync(fd);}need(same(fs.lstatSync(x,{bigint:true}))&&fs.realpathSync(x)===x,'path-after');const r={path:x,bytes:b.length,sha256:c.createHash('sha256').update(b).digest('hex')};if(i.sha256!==undefined)need(r.sha256===i.sha256,'hash');return {...r,body:b};}
const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});

const Q='/Volumes/AI_DATA/development/det-review-evidence/ri199-native-maximum-bound-buxv337k',P='/Volumes/AI_DATA/development/det-review-evidence/ri197-manual-original-pair-proof-dh668vz_';
const eq=(a,b)=>JSON.stringify(a)===JSON.stringify(b),cache=new Map();
function pin(i){let a=cache.get(i.path);if(!a){a=readExact(i);cache.set(i.path,a);}need(a.bytes===i.bytes&&a.sha256===i.sha256,'pin '+i.path);if(i.resolved_path!==undefined)need(i.resolved_path===i.path,'resolved');if(i.symlinks!==undefined)need(eq(i.symlinks,[]),'symlinks');return a;}
const refId={path:Q+'/SOURCE_REFERENCES.json',bytes:31518,sha256:'379eab32dcaa5e30835a693669fbef072923f8dc094a65afd4b63e1e0cec2b66'};
pin({path:Q+'/MAXIMUM_BOUND.md',bytes:14630,sha256:'0dea1b702c22c018cb6a7bd5546d99b5a91b16a3fff4bf9e66592e4113620662'});
pin({path:Q+'/HANDOFF.md',bytes:2377,sha256:'5a5eb351e51becc3e1e47b209cfc8411ff527e1de35a9dbad0c341fd5776af1b'});
const S=JSON.parse(pin(refId).body),M=new Map(S.direct_sources.map(r=>[r.identity.path,r]));
need(M.size===26&&eq([...M.keys()],[...M.keys()].sort()),'direct26 sorted');
need(S.direct_sources.reduce((n,r)=>n+r.identity.bytes,0)===1030155,'direct bytes');
for(const r of S.direct_sources){need(['administrative-reference','opaque-historical-support','accepted-analytic-text'].includes(r.access),'access class');pin(r.identity);}
const inherited=JSON.parse(pin(S.inherited_manifest_by_reference.identity).body);
need(inherited.protected_files.length===423&&S.inherited_manifest_by_reference.selected_paths===423&&S.inherited_manifest_by_reference.fresh423_file_or_transitive_typed_reference_recheck_claimed===false,'by-reference scope');
const boundaries=Object.fromEntries(Object.entries(inherited).filter(([k])=>!['schema','status','protected_files','scope'].includes(k)));
need(eq(boundaries,S.inherited_manifest_by_reference.boundary_objects)&&Object.keys(boundaries).length===15,'fifteen boundary objects unchanged');
need(S.inherited_manifest_by_reference.boundaries_are_preserved_historical_scope_not_current_read_authority===true&&S.inherited_manifest_by_reference.RI197_literal_certificate_exception_used_for_new_scientific_read===false&&S.inherited_manifest_by_reference.RI164_operational_boundary_remains_unexpanded===true,'historical scope');
let directReferences=0;
function direct(i){need(M.has(i.path),'selected direct reference');pin(i);directReferences++;}
for(const i of [S.assignment,S.accepted_predecessor,S.accepted_manual_packet,S.inherited_manifest_by_reference.identity,S.inherited_manifest_by_reference.acceptance])direct(i);
for(const group of S.current_complete_literal_read_groups)for(const i of group.sources)direct(i);
const h=JSON.parse(pin(S.accepted_manual_packet).body),names=fs.readdirSync(P).sort();
need(names.length===8&&eq(names,[...h.namespace].sort())&&eq(names,[...h.payloads.map(i=>p.basename(i.path)),'HANDOFF.json'].sort())&&eq(h.namespace,S.predecessor_namespace),'prior namespace8');
h.payloads.forEach(direct);
need(S.scientific_scope.new_scientific_body_read===false&&S.scientific_scope.scientific_JSON_parsed===false&&S.scientific_scope.automatic_arithmetic_graph_LP_or_scientific_execution===false&&S.scientific_scope.actual_W_or_H30_decided===false&&S.scientific_scope.ret_paused===true,'scientific scope');
need(eq(S.executable_obligations,{controls:92,recipes:34,mutation_families:35,focused_attempts:31,policy_cases:139,native_deeper:20,audit_deeper:42,new_credit:0,scope:'Required for their respective executable routes; no route is used or qualified by this manual analysis.'}),'obligations');
const final=['MAXIMUM_BOUND.md','SOURCE_REFERENCES.json','HANDOFF.md','AUTHOR_VERIFICATION.json','HANDOFF.json'].sort(),stage=process.argv[1]||'preseal3';
need(['preseal3','final5'].includes(stage),'stage');
const expected=stage==='final5'?final:final.filter(n=>!['AUTHOR_VERIFICATION.json','HANDOFF.json'].includes(n));
need(eq(fs.readdirSync(Q).sort(),expected),'current namespace');
const payloads=expected.map(n=>{const a=readExact({path:Q+'/'+n});cache.set(a.path,a);return simple(a);});
for(const n of ['MAXIMUM_BOUND.md','HANDOFF.md']){const text=cache.get(Q+'/'+n).body.toString('utf8');need(!/^(<{7}|={7}|>{7})( |$)/m.test(text)&&!/[ \t]+$/m.test(text),'text hygiene');for(const m of text.matchAll(/\[[^\]]+\]\(([^)]+)\)/g))need(expected.includes(m[1]),'local Markdown target');}
if(stage==='final5'){
const z=JSON.parse(cache.get(Q+'/HANDOFF.json').body);need(eq(z.namespace,final)&&z.payloads.length===4&&eq(z.payloads.map(i=>p.basename(i.path)).sort(),final.filter(n=>n!=='HANDOFF.json')),'seal coverage');z.payloads.forEach(pin);direct(z.assignment);direct(z.accepted_predecessor);
need(z.manual_analysis_only===true&&z.global_M6_upper_bound_proved===false&&z.concrete_parent_above_target_proved===false&&z.actual_W_decided===false&&z.new_scientific_body_read===false&&z.automated_proof_arithmetic_or_subject_execution===false&&z.qualification_credit===false&&z.repository_or_Git_written===false&&z.ret_paused===true,'scope of seal');
}
const all=[...cache.values()].map(simple);for(const i of all)readExact(i);
need(all.length===26+expected.length,'direct current fresh scope');
need(eq(fs.readdirSync(Q).sort(),expected)&&eq(fs.readdirSync(P).sort(),names),'post namespaces');
console.log(JSON.stringify({schema:'ri199-compact-administrative-check-v1',status:'IDENTITY_MATCH_NOT_MATHEMATICAL_ACCEPTANCE',stage,direct_sources:26,direct_bytes:1030155,inherited423_manifest_by_reference:true,fresh_inherited423_replay:false,inherited_boundary_objects_preserved:15,explicit_direct_reference_checks:directReferences,predecessor_namespace:8,current_namespace:expected.length,whole_identity_fresh_rechecks:all.length,current_payloads:payloads,scientific_body_read_or_proof_arithmetic:false,subject_execution:false},null,2));
